<template>
  <section class="session-history" aria-label="Supervision session history">
    <header class="history-heading">
      <div><h3>Supervision sessions</h3><p>Attendance, summaries, transcripts and the original time record.</p></div>
      <div class="actions"><button type="button" :disabled="loading" @click="refresh">{{ loading ? 'Refreshing…' : 'Refresh sessions' }}</button><button type="button" :disabled="!rows.length" @click="exportCsv">Export loaded sessions</button></div>
    </header>
    <div class="history-filters">
      <label>Find a session<input v-model="search" type="search" placeholder="Date, supervisor, session type or notes"></label>
      <label>Attendance<select v-model="attendance"><option value="all">All outcomes</option><option value="attended">Attended</option><option value="missed">Missed supervision</option><option value="excused">Excused absence</option><option value="cancelled">Cancelled / rescheduled</option><option value="unknown">No outcome recorded</option></select></label>
      <label>Sort<select v-model="sort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="attendance">Attendance outcome</option><option value="duration">Attended minutes: most first</option></select></label>
    </div>
    <p class="scope-note">{{ filtered.length }} shown · {{ rows.length }} loaded sessions{{ hasMore ? ' · more history is available below' : ' · all available history loaded' }}. Zero recorded minutes alone does not establish a missed session.</p>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
    <div class="history-list">
      <article v-for="session in filtered" :key="session.id" class="session-row">
        <button type="button" class="session-toggle" :aria-expanded="expandedId === session.id" @click="open(session)">
          <span><strong>{{ when(session.startAt) }}</strong><small>{{ session.sessionType || 'Individual' }} supervision · {{ session.supervisorName || 'Supervisor' }}</small></span>
          <span class="outcome" :class="sessionAttendanceState(session)">{{ sessionAttendanceLabels[sessionAttendanceState(session)] }}<small v-if="sessionAttendanceState(session) === 'attended'">{{ minutes(session.totalSeconds) }} attended minutes</small></span>
          <span>{{ expandedId === session.id ? 'Close details' : 'View session' }}</span>
        </button>
        <div v-if="expandedId === session.id" class="session-detail">
          <p class="session-meta">{{ when(session.startAt) }} – {{ when(session.endAt) }} · {{ timezone }} · Session #{{ session.id }}</p>
          <p v-if="session.attendanceReason" class="outcome-reason"><strong>Attendance record:</strong> {{ session.attendanceReason }}</p>
          <p v-if="session.notes" class="preserve-lines">{{ session.notes }}</p>
          <nav class="record-tabs" aria-label="Session record sections"><button v-for="tab in recordTabs" :key="tab.id" type="button" :aria-pressed="recordTab === tab.id" @click="recordTab = tab.id">{{ tab.label }}</button></nav>
          <p v-if="artifactLoading" role="status">Loading saved transcript and summary…</p>
          <p v-if="artifactError" class="error" role="alert">{{ artifactError }}</p>
          <div v-if="recordTab === 'summary'" class="reading-view">
            <h4>{{ session.focusTitle || 'Session summary' }}</h4>
            <div v-if="draft.summaryText" class="markdown-summary" v-html="summaryHtml" />
            <p v-else>No summary has been saved for this session.</p>
            <template v-if="session.goals?.length"><h4>Goals</h4><ul><li v-for="(goal,index) in session.goals" :key="goal.id || index">{{ goal.done ? 'Completed: ' : '' }}{{ goal.text }}</li></ul></template>
            <template v-if="session.actionItems?.length"><h4>Action items</h4><ul><li v-for="(item,index) in session.actionItems" :key="item.id || index">{{ item.done ? 'Completed: ' : '' }}{{ item.text }}</li></ul></template>
            <p v-if="session.hoursAttended != null">Requirement credit: {{ session.hoursAttended }} hours<template v-if="session.hoursBefore != null && session.hoursAfter != null"> · {{ session.hoursBefore }} before → {{ session.hoursAfter }} after</template>.</p>
          </div>
          <div v-else-if="recordTab === 'transcript'" class="reading-view"><h4>Full transcript</h4><a v-if="transcriptLink" :href="transcriptLink" target="_blank" rel="noopener noreferrer">Open attached transcript</a><p v-if="draft.transcriptUrl && !transcriptLink" class="error">The saved transcript link cannot be opened safely. Use a full http or https address.</p><div v-if="draft.transcriptText" class="preserve-lines transcript-text">{{ draft.transcriptText }}</div><p v-else>No transcript text has been saved.</p></div>
          <section v-else-if="recordTab === 'activity'" class="session-activity" aria-label="Meeting chat, polls and questions">
            <div class="activity-heading"><h4>Meeting chat, polls &amp; Q&amp;A</h4><button type="button" :disabled="activityLoading" @click="loadActivity(true)">Refresh meeting activity</button></div>
            <p class="scope-note">Messages available under your existing meeting permissions. Showing up to 500 saved events.</p>
            <p v-if="activityLoading" role="status">Loading meeting activity…</p><p v-if="activityError" class="error" role="alert">{{ activityError }}</p>
            <p v-if="!activityLoading && !activityError && !currentActivity.length">No meeting chat, polls or Q&amp;A were recorded.</p>
            <ol v-if="currentActivity.length" class="activity-list"><li v-for="item in currentActivity" :key="item.id"><div class="activity-meta"><strong>{{ activityAuthor(item) }}</strong><span>{{ activityLabel(item) }} · {{ when(item.createdAt) }}</span></div><template v-if="item.activityType === 'poll'"><p>{{ item.payload?.question || 'Poll question not saved' }}</p><ul><li v-for="(option,index) in pollOptions(item)" :key="index">{{ option }}</li></ul></template><p v-else-if="item.activityType === 'poll_vote'">{{ pollVote(item) }}</p><p v-else>{{ item.payload?.text || 'No text saved' }}</p></li></ol>
          </section>
          <SupervisionRecordPanel v-show="recordTab === 'attendance'" :session-id="Number(session.id)" :provider-id="providerId" :timezone="timezone" @record="record = $event" @changed="onRecordChanged" @open-notes="recordTab = 'summary'" />
          <form v-if="recordTab === 'edit' && record?.canManage" class="artifact-editor" @submit.prevent="saveArtifact(false)">
            <label>Transcript attachment URL<input v-model="draft.transcriptUrl" type="url" @input="cacheDraft('transcriptUrl',$event)" placeholder="https://…"></label>
            <label>Transcript text<textarea ref="transcriptEditor" v-model="draft.transcriptText" rows="10" @input="cacheDraft('transcriptText',$event);grow($event.target)" /></label>
            <label>Summary<textarea ref="summaryEditor" v-model="draft.summaryText" rows="10" @input="cacheDraft('summaryText',$event);grow($event.target)" /></label>
            <div class="actions"><button type="submit" :disabled="artifactBusy">{{ artifactBusy ? 'Saving…' : 'Save transcript and summary' }}</button><button type="button" :disabled="artifactBusy || !draft.transcriptText.trim()" @click="saveArtifact(true)">Generate summary</button></div>
          </form>
          <button v-if="canFinalize(session)" type="button" :disabled="finalizing" @click="finalize(session)">{{ finalizing ? 'Submitting…' : 'Submit completed session' }}</button>
        </div>
      </article>
    </div>
    <p v-if="!loading && !filtered.length">{{ rows.length ? 'No loaded sessions match these filters.' : 'No past supervision sessions found.' }}</p>
    <button v-if="hasMore" type="button" class="load-more" :disabled="loading" @click="loadMore">{{ loading ? 'Loading history…' : 'Load more sessions' }}</button>
  </section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,reactive,ref,watch} from 'vue';
import {marked} from 'marked';
import DOMPurify from 'dompurify';
import api from '../../services/api';
import SupervisionRecordPanel from '../schedule/SupervisionRecordPanel.vue';
import {parseScheduleUtcInstant} from '../../utils/scheduleEventInstants.js';
import {sessionAttendanceState,supervisionSessionCounts,sessionAttendanceLabels,safeTranscriptUrl} from '../../utils/superviseeSessionHistory.js';
const props=defineProps({agencyId:{type:Number,required:true},providerId:{type:Number,required:true},sessions:{type:Array,default:undefined},hasMoreSessions:{type:Boolean,default:undefined},timezone:{type:String,default:'America/Denver'},attendanceFilter:{type:String,default:'all'},attendanceSummary:{type:Object,default:null}});
const emit=defineEmits(['refreshed','changed','counts','update:attendanceFilter']);
const rows=ref([]),loading=ref(false),error=ref(''),notice=ref(''),page=ref(1),hasMore=ref(false),search=ref(''),attendance=ref('all'),sort=ref('newest'),expandedId=ref(null),recordTab=ref('summary'),record=ref(null),artifactLoading=ref(false),artifactBusy=ref(false),artifactError=ref(''),finalizing=ref(false),transcriptEditor=ref(null),summaryEditor=ref(null);
const completeAttendanceSummary=ref(null);
const activityBySession=ref({}),activityLoading=ref(false),activityError=ref('');
const currentActivity=computed(()=>activityBySession.value[expandedId.value] || []);
const draft=reactive({transcriptUrl:'',transcriptText:'',summaryText:''});
const draftCache=new Map();
let generation=0,artifactVersion=0,active=true;
onBeforeUnmount(()=>{active=false;generation++;artifactVersion++;});
const when=value=>{const date=parseScheduleUtcInstant(value);return date?new Intl.DateTimeFormat(undefined,{timeZone:props.timezone,year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(date):'Date unavailable';};
const minutes=seconds=>Math.round(Number(seconds || 0)/6)/10;
const filtered=computed(()=>rows.value.filter(session=>(attendance.value==='all'||sessionAttendanceState(session)===attendance.value)&&(!search.value.trim()||[when(session.startAt),session.supervisorName,session.sessionType,session.notes,session.attendanceReason,sessionAttendanceLabels[sessionAttendanceState(session)]].join(' ').toLowerCase().includes(search.value.trim().toLowerCase()))).slice().sort((a,b)=>sort.value==='oldest'?(parseScheduleUtcInstant(a.startAt)||0)-(parseScheduleUtcInstant(b.startAt)||0):sort.value==='duration'?Number(b.totalSeconds||0)-Number(a.totalSeconds||0):sort.value==='attendance'?sessionAttendanceState(a).localeCompare(sessionAttendanceState(b)):(parseScheduleUtcInstant(b.startAt)||0)-(parseScheduleUtcInstant(a.startAt)||0)));
const transcriptLink=computed(()=>safeTranscriptUrl(draft.transcriptUrl));
const summaryHtml=computed(()=>DOMPurify.sanitize(marked.parse(draft.summaryText||'',{async:false}),{ALLOWED_TAGS:['p','br','h1','h2','h3','h4','ul','ol','li','strong','b','em','i','blockquote','code','pre','hr'],ALLOWED_ATTR:[]}));
const recordTabs=computed(()=>[{id:'summary',label:'Summary & details'},{id:'transcript',label:'Transcript'},{id:'attendance',label:'Attendance & edit time'},{id:'activity',label:'Chat, polls & Q&A'},...(record.value?.canManage?[{id:'edit',label:'Edit transcript & summary'}]:[])]);
function publish(){emit('refreshed',rows.value.slice(),{hasMore:hasMore.value,page:page.value,pageSize:50,attendanceSummary:completeAttendanceSummary.value});emit('counts',supervisionSessionCounts(rows.value));}
async function fetchPage(nextPage,append=false){if(loading.value)return;const g=generation;loading.value=true;error.value='';try{const {data}=await api.get(`/supervision/supervisee/${props.providerId}/sessions`,{params:{agencyId:props.agencyId,page:nextPage,pageSize:50},skipGlobalLoading:true});if(!active||g!==generation)return;const incoming=Array.isArray(data?.sessions)?data.sessions:[];rows.value=append?[...new Map([...rows.value,...incoming].map(row=>[Number(row.id),row])).values()]:incoming;page.value=nextPage;hasMore.value=data.hasMore===true;completeAttendanceSummary.value=data.attendanceSummary || null;publish();}catch(e){if(active&&g===generation)error.value=e.response?.data?.error?.message||'Unable to load supervision history.';}finally{if(active&&g===generation)loading.value=false;}}
function refresh(){return fetchPage(1);}
function loadMore(){return fetchPage(page.value+1,true);}
function cacheDraft(field,event){draft[field]=event.target.value;if(expandedId.value)draftCache.set(Number(expandedId.value),{...draft});}
function setDraft(artifact){draft.transcriptUrl=String(artifact?.transcriptUrl??artifact?.transcript_url??'');draft.transcriptText=String(artifact?.transcriptText??artifact?.transcript_text??'');draft.summaryText=String(artifact?.summaryText??artifact?.summary_text??'');}
async function open(session){if(expandedId.value===session.id){expandedId.value=null;artifactVersion++;return;}expandedId.value=session.id;recordTab.value='summary';record.value=null;artifactBusy.value=false;activityLoading.value=false;activityError.value='';notice.value='';artifactError.value='';setDraft(draftCache.get(Number(session.id)) || session);if(draftCache.has(Number(session.id))){artifactVersion++;artifactLoading.value=false;return;}const version=++artifactVersion;artifactLoading.value=true;try{const {data}=await api.get(`/supervision/sessions/${session.id}/artifacts`,{skipGlobalLoading:true});if(active&&version===artifactVersion&&expandedId.value===session.id&&data.artifact&&!draftCache.has(Number(session.id)))setDraft(data.artifact);}catch(e){if(active&&version===artifactVersion)artifactError.value=e.response?.data?.error?.message||'Unable to refresh the saved transcript and summary.';}finally{if(active&&version===artifactVersion)artifactLoading.value=false;}}
function activityAuthor(item){return String(item.payload?.authorName || record.value?.participants?.find(person=>Number(person.userId)===Number(item.userId))?.name || 'Participant');}
function activityLabel(item){return ({chat:item.recipientUserId?'Private message':'Chat message',poll:'Poll',poll_vote:'Poll response',question:'Question',answer:'Answer'})[item.activityType] || 'Meeting activity';}
function pollOptions(item){return Array.isArray(item.payload?.options)?item.payload.options.map(option=>typeof option==='string'?option:String(option?.text || option?.label || 'Option')):[];}
function pollVote(item){const poll=currentActivity.value.find(event=>event.activityType==='poll'&&String(event.payload?.id || event.id)===String(item.payload?.pollId));const options=poll?pollOptions(poll):[];const index=Number(item.payload?.optionIndex);return poll&&Number.isInteger(index)&&index>=0&&options[index]!=null?`${poll.payload.question}: ${options[index]}`:'Poll response recorded; the selected option is unavailable.';}
async function loadActivity(force=false){const sid=expandedId.value,version=artifactVersion;if(!sid||activityLoading.value||(!force&&activityBySession.value[sid]))return;activityLoading.value=true;activityError.value='';try{const {data}=await api.get(`/supervision/sessions/${sid}/activity`,{skipGlobalLoading:true});if(!active||version!==artifactVersion||expandedId.value!==sid)return;activityBySession.value={...activityBySession.value,[sid]:Array.isArray(data.activity)?data.activity:[]};}catch(e){if(active&&version===artifactVersion)activityError.value=e.response?.data?.error?.message||'Unable to load meeting activity.';}finally{if(active&&version===artifactVersion)activityLoading.value=false;}}
function grow(element){if(Array.isArray(element)){element.forEach(grow);return;}if(!element?.style)return;element.style.height='auto';element.style.height=`${Math.max(180,element.scrollHeight)}px`;}
watch(recordTab,async value=>{if(value==='activity')void loadActivity();if(value==='edit'){await nextTick();grow(transcriptEditor.value);grow(summaryEditor.value);}});
async function saveArtifact(autoSummarize){if(artifactBusy.value)return;if(draft.transcriptUrl&&!safeTranscriptUrl(draft.transcriptUrl)){artifactError.value='Use a full http or https transcript URL.';return;}const sid=expandedId.value,version=artifactVersion;artifactBusy.value=true;artifactError.value='';notice.value='';try{const {data}=await api.post(`/supervision/sessions/${sid}/artifacts`,{transcriptUrl:draft.transcriptUrl.trim()||null,transcriptText:draft.transcriptText.trim()||null,summaryText:autoSummarize?undefined:draft.summaryText.trim()||null,autoSummarize},{skipGlobalLoading:true});if(!active||version!==artifactVersion)return;if(data.artifact)setDraft(data.artifact);draftCache.delete(Number(sid));rows.value=rows.value.map(row=>row.id===sid?{...row,...draft}:row);recordTab.value='summary';notice.value=autoSummarize&&!draft.summaryText.trim()?'No summary was returned. The saved transcript remains available.':'Session transcript and summary saved.';publish();}catch(e){if(active&&version===artifactVersion)artifactError.value=e.response?.data?.error?.message||'Unable to save this session record.';}finally{if(active&&version===artifactVersion)artifactBusy.value=false;}}
async function onRecordChanged(){if(props.sessions===undefined)await refresh();emit('changed');}
function canFinalize(session){return record.value?.canManage&&parseScheduleUtcInstant(session.endAt)<new Date()&&!['FINALIZED','MISSED','CANCELLED','RESCHEDULED','MANUAL_PENDING','MANUAL_RECORDING'].includes(String(session.status).toUpperCase());}
async function finalize(session){finalizing.value=true;error.value='';try{await api.post(`/supervision/sessions/${session.id}/finalize`,{markMissed:false},{skipGlobalLoading:true});await onRecordChanged();}catch(e){error.value=e.response?.data?.error?.message||'Unable to submit this session.';}finally{finalizing.value=false;}}
function exportCsv(){const cell=value=>`"${String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')}"`;const data=[['Session ID','Start','End','Supervisor','Type','Attendance outcome','Attended minutes','Attendance reason'],...filtered.value.map(s=>[s.id,s.startAt,s.endAt,s.supervisorName,s.sessionType,sessionAttendanceLabels[sessionAttendanceState(s)],s.totalSeconds==null?'':minutes(s.totalSeconds),s.attendanceReason])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([data],{type:'text/csv;charset=utf-8;'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='supervision-session-history.csv';anchor.click();URL.revokeObjectURL(url);}
watch(()=>[props.agencyId,props.providerId],()=>{generation++;artifactVersion++;draftCache.clear();completeAttendanceSummary.value=null;activityBySession.value={};activityLoading.value=false;activityError.value='';expandedId.value=null;rows.value=[];page.value=1;loading.value=false;artifactBusy.value=false;artifactLoading.value=false;error.value='';notice.value='';if(props.sessions===undefined)void refresh();},{immediate:true});
watch(()=>props.sessions,value=>{if(value!==undefined){rows.value=value.slice();page.value=Math.max(1,Math.ceil(value.length/50));hasMore.value=props.hasMoreSessions??(value.length>0&&value.length%50===0);emit('counts',supervisionSessionCounts(rows.value));}},{immediate:true});
watch(attendance,value=>emit('update:attendanceFilter',value));
watch(()=>props.attendanceFilter,value=>{if(['all','attended','missed','excused','cancelled','unknown'].includes(value))attendance.value=value;},{immediate:true});
watch(()=>props.attendanceSummary,value=>{completeAttendanceSummary.value=value;},{immediate:true});
watch(()=>props.hasMoreSessions,value=>{if(value!==undefined)hasMore.value=value;});
defineExpose({refresh});
</script>
<style scoped>
.session-history{color:#172b43;background:#fff;border:1px solid #d5dfea;border-radius:16px;padding:20px}.history-heading,.actions{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.history-heading h3{margin:0;font-size:1.2rem}.history-heading p,.scope-note,.session-meta{color:#52637a;font-size:.88rem;line-height:1.5}.history-filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;margin:18px 0 10px}label{display:flex;flex-direction:column;gap:6px;font-size:.9rem;font-weight:600}input,select,textarea{box-sizing:border-box;width:100%;padding:10px;border:1px solid #afbed0;border-radius:8px;background:#fff;color:#172b43;font:inherit}button{padding:10px 14px;min-height:42px;border:1px solid #afbed0;border-radius:8px;color:#173f67;background:#f1f6fc;font:inherit;font-weight:600;cursor:pointer}button:disabled{opacity:.55;cursor:default}button:focus-visible,a:focus-visible{outline:3px solid #2d74b8;outline-offset:3px}.session-row{border:1px solid #d5dfea;border-radius:12px;margin-top:10px;overflow:hidden}.session-toggle{width:100%;border:0;border-radius:0;background:#fff;display:grid;grid-template-columns:1.5fr 1fr auto;gap:15px;align-items:center;text-align:left;padding:16px}.session-toggle:hover{background:#f3f7fc}.session-toggle small{display:block;margin-top:6px;color:#53647b;font-weight:400;font-size:.82rem}.outcome{font-size:.85rem;color:#354d69}.outcome.missed{color:#a02525}.outcome.attended{color:#176243}.outcome.excused{color:#77540f}.session-detail{padding:0 18px 20px;border-top:1px solid #e0e7ef}.record-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.record-tabs [aria-pressed=true]{background:#173f67;border-color:#173f67;color:#fff}.reading-view{padding:8px 0;line-height:1.7;overflow-wrap:anywhere}.reading-view h4{margin:10px 0}.preserve-lines,.transcript-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.transcript-text{margin-top:16px}.activity-heading,.activity-meta{display:flex;gap:10px;justify-content:space-between;align-items:center;flex-wrap:wrap}.activity-meta span{font-size:.8rem;color:#52637a}.activity-list{list-style:none;margin:12px 0;padding:0}.activity-list>li{border:1px solid #d5dfea;border-radius:10px;padding:14px;margin-top:10px}.activity-list p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.activity-list ul{list-style:disc;padding-left:24px}.artifact-editor{display:grid;gap:18px}.artifact-editor textarea{overflow:hidden;resize:vertical;line-height:1.6;min-height:180px;max-height:none}.outcome-reason{padding:12px;border-left:4px solid #43729e;background:#f2f6fc;white-space:pre-wrap}.error{color:#a02525}.load-more{margin-top:18px;width:100%}.markdown-summary :deep(pre){white-space:pre-wrap;overflow-wrap:anywhere}.markdown-summary :deep(h1){font-size:1.4rem}.markdown-summary :deep(h2){font-size:1.2rem}@media(max-width:650px){.session-history{padding:14px}.history-filters{grid-template-columns:1fr}.session-toggle{grid-template-columns:1fr;gap:10px}.session-detail{padding:0 12px 16px}.record-tabs button{flex:1 1 45%}}
</style>
